{code:javascript}const fs = require('fs');

const path = '/Users/sergey/Downloads/fingerprint/';

const instruments = {}
const instrumentsData = JSON.parse(fs.readFileSync(path + 'instruments.json'));
for (const e of instrumentsData) {
    instruments[e.payment_method_id] = {
        paymentUserId: e.payment_user_id,
        token: e.payment_method_id
    };
}

const hashes = {}
const hashesData = JSON.parse(fs.readFileSync(path + 'hashes.json'));
for (const e of hashesData) {
    const token = e.paymentInstrumentId.replace('processout/', '')
    if (token in instruments) {
        hashes[e.hash] = {
            ...instruments[token],
            hash: e.hash
        }
    }
}

const fingerprintsData = JSON.parse(fs.readFileSync(path + 'fingerprints.json'));
for (const e of fingerprintsData) {
    if (e.hash in hashes) {
       hashes[e.hash].fingerprint = e.fingerprint
    }
}

const res = Object.values(hashes);
for (const e of res) {
    if (!e.fingerprint) {
        console.log(e.token)
    }
}

const updateSize = 5000;
for (let i = 0; i < res.length; i += updateSize) {
    const batch = res.slice(i, i + updateSize);

    const text = batch.map(e =>
        `UPDATE payment_method_user ` +
        `SET card_alias = '${e.fingerprint}' ` +
        `WHERE payment_user_id = ${e.paymentUserId} ` +
        `AND payment_method_type = 'processout' ` +
        `AND payment_method_id = '${e.token}' ` +
        `AND card_alias IS NULL;`
    ).join('\n')

    fs.writeFileSync(path + '/update_' + i + '.sql', text);
}{code}

